CREATE TABLE IF NOT EXISTS gis_phase343_crosswalk (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), crosswalk_version TEXT NOT NULL, source_feature_id UUID NOT NULL, target_feature_id UUID NOT NULL, source_provider TEXT NOT NULL, target_provider TEXT NOT NULL, source_name TEXT, target_name TEXT, source_state_code TEXT, target_state_code TEXT, name_similarity DOUBLE PRECISION NOT NULL DEFAULT 0, state_match BOOLEAN NOT NULL DEFAULT false, parent_match BOOLEAN NOT NULL DEFAULT false, crosswalk_score DOUBLE PRECISION NOT NULL DEFAULT 0, decision TEXT NOT NULL DEFAULT 'REVIEW', rationale JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(crosswalk_version,source_feature_id,target_feature_id));